-- 新增注销发起通知模板：允许申诉 / 不允许申诉。
-- 执行前请确认 noticeTemplateV2 中不存在相同 templateName。

INSERT INTO public."noticeTemplateV2" (id, remarks, "createTime", "updateTime", "deleteTime", version, templates, label, "templateParams", "templateName", node) VALUES ('d6a1e235-5a84-4fc7-9a12-2ea8de230001', '注销发起-允许申诉', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, null, 2, '{"emails":[{"email":{"text":"<h3>尊敬的 <%verifiedName%>：</h3>\n<p>我们很遗憾地通知您，基于风险等因素综合考量，我们已启动对您的 Qbit 账户进行关户处理。</p>\n<p>在关闭账户之前，我们会进行严格的审查，同时也给您提供了申诉通道。在申诉期间，账户功能和资金将会暂时冻结无法使用。如果您需要，可以回复邮件，提供材料证明并详细说明账户使用情况，我们将充分考虑您的申诉，并做出最终决定。申诉请发送申诉材料邮件至：support@qbitnetwork.com。</p>\n<p>自本邮件发送之时计算，若两个工作日内未收到您的任何答复，将视为您已接受关户处理，我们将正式关闭您的账户，并逐步开始资金清算，请关注我们的邮件通知。</p>\n<p>如有任何问题，请联系客服或您的客户经理。客服电话：0571-88375867。</p>\n<p>感谢您选择 Qbit！</p>","allow":true,"tenant":true,"template":"customUniteNotice","topicName":"[<%emailPrefix%>]您的账户将被关户处理"},"language":"zh"},{"email":{"text":"<h3>Dear <%verifiedName%>,</h3>\n<p>We regret to inform you that, following a risk assessment, we have initiated the closure of your Interlace account.</p>\n<p>Before the account is closed, a formal review will be conducted. You may submit an appeal during this period. While the appeal is under review, your account and funds will remain temporarily frozen.</p>\n<p>If you wish to appeal, please reply to this email with supporting documents and a detailed explanation of your account activity. Appeals should be submitted to: support@interlace.money</p>\n<p>If no response is received within two business days from the time this email is sent, the account closure will proceed. We will then begin the fund settlement process and notify you accordingly.</p>","allow":true,"tenant":true,"template":"customUniteNotice","topicName":"[<%emailPrefix%>]Account Closure in Progress"},"language":"en"}],"sockets":[{"socket":{"text":"<h3>尊敬的 <%verifiedName%>：</h3>\n<p>我们很遗憾地通知您，基于风险等因素综合考量，我们已启动对您的 Qbit 账户进行关户处理。</p>\n<p>在关闭账户之前，我们会进行严格的审查，同时也给您提供了申诉通道。在申诉期间，账户功能和资金将会暂时冻结无法使用。如果您需要，可以回复邮件，提供材料证明并详细说明账户使用情况，我们将充分考虑您的申诉，并做出最终决定。申诉请发送申诉材料邮件至：support@qbitnetwork.com。</p>\n<p>自本邮件发送之时计算，若两个工作日内未收到您的任何答复，将视为您已接受关户处理，我们将正式关闭您的账户，并逐步开始资金清算，请关注我们的邮件通知。</p>\n<p>如有任何问题，请联系客服或您的客户经理。客服电话：0571-88375867。</p>\n<p>感谢您选择 Qbit！</p>","type":"Other","allow":true,"title":"通知-您的账户将被关户处理","tenant":true,"subType":"notice","notificationToAccountType":"User"},"language":"zh"},{"socket":{"text":"<h3>Dear <%verifiedName%>,</h3>\n<p>We regret to inform you that, following a risk assessment, we have initiated the closure of your Interlace account.</p>\n<p>Before the account is closed, a formal review will be conducted. You may submit an appeal during this period. While the appeal is under review, your account and funds will remain temporarily frozen.</p>\n<p>If you wish to appeal, please reply to this email with supporting documents and a detailed explanation of your account activity. Appeals should be submitted to: support@interlace.money</p>\n<p>If no response is received within two business days from the time this email is sent, the account closure will proceed. We will then begin the fund settlement process and notify you accordingly.</p>","type":"Other","allow":true,"title":"Notice-Account Closure in Progress","tenant":true,"subType":"notice","notificationToAccountType":"User"},"language":"en"}],"qbitNotices":[],"adminSockets":[],"feiShuRobots":[],"earmarkEmails":[]}', '注销发起-允许申诉', '[{"name":"verifiedName","type":"string","remarks":"账户名称","require":false},{"name":"webUrl","type":"string","remarks":"商户端链接","require":false},{"name":"emailPrefix","type":"string","remarks":"邮件标题前缀","require":false},{"name":"serviceApiUrl","type":"string","remarks":"服务器域名","require":false},{"name":"mobileUrl","type":"string","remarks":"移动端链接","require":false}]', 'ACCOUNT_INACTIVE_SUBMITTED_APPEAL', 'java');

INSERT INTO public."noticeTemplateV2" (id, remarks, "createTime", "updateTime", "deleteTime", version, templates, label, "templateParams", "templateName", node) VALUES ('d6a1e235-5a84-4fc7-9a12-2ea8de230002', '注销发起-不允许申诉', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, null, 2, '{"emails":[{"email":{"text":"<h3>尊敬的 <%verifiedName%>：</h3>\n<p>您好！感谢您一直以来对 Qbit 的支持。根据合规管理与相关服务协议要求，您的账户已被纳入注销清退流程。</p>\n<p>本通知为注销流程的正式启动说明。自本通知发送之日起，您的账户服务及相关功能将分阶段关闭。我们将对您名下的账户资金进行清算，清算过程中将产生 <%amount%> USD 的清算手续费。</p>\n<p>请关注后续邮件通知，并根据指引配合完成资金处理与账目核对。</p>\n<p>如有任何问题，请联系客服或您的客户经理。客服电话：0571-88375867，客服邮箱：support@qbitnetwork.com。</p>","allow":true,"tenant":true,"template":"customUniteNotice","topicName":"[<%emailPrefix%>]关于您的账户启动注销及清算通知"},"language":"zh"},{"email":{"text":"<h3>Dear <%verifiedName%>,</h3>\n<p>Your account has been placed into offboarding in accordance with our compliance requirements and applicable service agreements.</p>\n<p>Effective from the date of this notice, your account services and related features will be gradually closed. Your account balance will be settled during this process, and a USD <%amount%> offboarding fee will apply.</p>\n<p>Please monitor your email for further instructions and complete the necessary fund settlement and reconciliation procedures accordingly.</p>","allow":true,"tenant":true,"template":"customUniteNotice","topicName":"[<%emailPrefix%>]Account Offboarding Initiated"},"language":"en"}],"sockets":[{"socket":{"text":"<h3>尊敬的 <%verifiedName%>：</h3>\n<p>您好！感谢您一直以来对 Qbit 的支持。根据合规管理与相关服务协议要求，您的账户已被纳入注销清退流程。</p>\n<p>本通知为注销流程的正式启动说明。自本通知发送之日起，您的账户服务及相关功能将分阶段关闭。我们将对您名下的账户资金进行清算，清算过程中将产生 <%amount%> USD 的清算手续费。</p>\n<p>请关注后续邮件通知，并根据指引配合完成资金处理与账目核对。</p>\n<p>如有任何问题，请联系客服或您的客户经理。客服电话：0571-88375867，客服邮箱：support@qbitnetwork.com。</p>","type":"Other","allow":true,"title":"通知-关于您的账户启动注销及清算通知","tenant":true,"subType":"notice","notificationToAccountType":"User"},"language":"zh"},{"socket":{"text":"<h3>Dear <%verifiedName%>,</h3>\n<p>Your account has been placed into offboarding in accordance with our compliance requirements and applicable service agreements.</p>\n<p>Effective from the date of this notice, your account services and related features will be gradually closed. Your account balance will be settled during this process, and a USD <%amount%> offboarding fee will apply.</p>\n<p>Please monitor your email for further instructions and complete the necessary fund settlement and reconciliation procedures accordingly.</p>","type":"Other","allow":true,"title":"Notice-Account Offboarding Initiated","tenant":true,"subType":"notice","notificationToAccountType":"User"},"language":"en"}],"qbitNotices":[],"adminSockets":[],"feiShuRobots":[],"earmarkEmails":[]}', '注销发起-不允许申诉', '[{"name":"verifiedName","type":"string","remarks":"账户名称","require":false},{"name":"webUrl","type":"string","remarks":"商户端链接","require":false},{"name":"emailPrefix","type":"string","remarks":"邮件标题前缀","require":false},{"name":"serviceApiUrl","type":"string","remarks":"服务器域名","require":false},{"name":"mobileUrl","type":"string","remarks":"移动端链接","require":false},{"name":"amount","type":"string","remarks":"清退手续费","require":true}]', 'ACCOUNT_INACTIVE_SUBMITTED_NO_APPEAL', 'java');
